import tables from "@/data/tables";
import queries from "@/data/queries";
import { ref } from "vue";
export default {
  name: "NavbarMenu",
  methods: {
    handle(name) {
      this.$router.push({
        name: name
      });
    },

    secondHandle(name, path) {
      this.$router.push({
        name: name,
        params: {
          link: path,
          name: name
        }
      });
    }

  },

  setup() {
    const allTables = ref(tables);
    const allQueries = ref(queries);
    return {
      allTables,
      allQueries
    };
  }

};
